-- Seed catalogue: 25 starter products (same as the Muse store).
-- Run after schema.sql in Supabase SQL Editor.
-- Prices are PKR. Midnight Puffer Jacket Rs 8,999 and Emerald Embroidered Shawl Rs 2,999 are the live prices.

on conflict (id) do update set name = excluded.name, price = excluded.price, old_price = excluded.old_price, image = excluded.image, stock = excluded.stock;
